{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "resolution_time",
  "per_column": [
    {
      "name": "problem_domain",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Derived from short_description/category, this categorizes the issue type. It is known at intake, lies outside resolution_time, and different domains plausibly differ in how long they take to resolve."
    },
    {
      "name": "incident_severity_urgency",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Captures severity/urgency (system_down vs informational), knowable early and independent of resolution_time; a plausible driver of resolution duration."
    },
    {
      "name": "scope_indicator",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "System-wide vs user-level scope is available at intake and outside the focus; broader scope plausibly correlates with longer resolution."
    },
    {
      "name": "resolution_ownership_mismatch",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Framed around 'resolution' ownership mismatch, this is likely derived from closure/reassignment fields that are only settled once the incident is being/has been resolved, so it risks encoding post-outcome information rather than a pre-resolution signal."
    },
    {
      "name": "technical_complexity_signal",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Complexity/technology category is knowable from the description at intake, sits outside the focus, and complexity plausibly predicts resolution duration."
    },
    {
      "name": "responder_expertise_mismatch",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Whether a domain expert vs generalist is assigned (and escalation need) is largely determinable at assignment time, is distinct from resolution_time, and expertise mismatch plausibly lengthens resolution. Escalation_required carries mild leakage risk but overall functions as a predictor."
    },
    {
      "name": "incident_closure_status",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Whether the incident is closed vs open is a direct function of the outcome; resolution_time is only well-defined/measurable for closed incidents, so this restates/leaks the outcome rather than predicting it."
    }
  ],
  "n_predictors": 5,
  "predictive_utility": 0.6,
  "rationale": "Five columns (problem_domain, incident_severity_urgency, scope_indicator, technical_complexity_signal, responder_expertise_mismatch) are legitimate, intake- or assignment-time predictors that add genuine signal beyond the raw fields for modeling resolution_time. Two columns fail: incident_closure_status directly encodes the outcome (leakage/restatement), and resolution_ownership_mismatch is defined around the resolution process and likely encodes post-outcome information. The valid set provides moderate-to-good leverage, but some features are partly redundant with existing priority/category columns and two clear leakage columns lower the overall quality."
}

